164	int main(void)
165	{
166	    prvSetupHardware();
167	
168	    /* Tạo queue chứa sự kiện nút bấm */
169	    xButtonQueue = xQueueCreate(4, sizeof(uint32_t));
170	    xUIQueue     = xQueueCreate(4, sizeof(uint32_t));
171	
172	    /* Tạo các tác vụ ứng dụng LED, nút bấm và hiển thị LCD */
173	    xTaskCreate(vTaskLED1,    "LED1_1000ms", configMINIMAL_STACK_SIZE,       NULL, tskIDLE_PRIORITY + 1, NULL);
174	    xTaskCreate(vTaskLED2,    "LED2_400ms",  configMINIMAL_STACK_SIZE,       NULL, tskIDLE_PRIORITY + 1, NULL);
175	    xTaskCreate(vTaskButton,  "BtnPoll",     configMINIMAL_STACK_SIZE,       NULL, tskIDLE_PRIORITY + 2, NULL);
176	    xTaskCreate(vTaskLED3,    "LED3_Queue",  configMINIMAL_STACK_SIZE,       NULL, tskIDLE_PRIORITY + 1, NULL);
177	    xTaskCreate(vTaskMonitor, "Monitor",     configMINIMAL_STACK_SIZE,       NULL, tskIDLE_PRIORITY + 1, NULL);
178	    xTaskCreate(vTaskLCD,      "LCD_Task",    configMINIMAL_STACK_SIZE * 4,   NULL, tskIDLE_PRIORITY + 1, NULL);
179	
180	    /* Bắt đầu FreeRTOS scheduler */
181	    vTaskStartScheduler();
182	
183	    /* Không bao giờ tới đây */
184	    for (;;);
185	    return 0;
186	}

